public class Demo {
    public static void main(String[] args) {
        int i = 1;                 // initialization
        while (i <= 5) {           // condition
            System.out.println(i);
            i++;                   // increment
        }
    }
}

public class Demo {
    public static void main(String[] args) {
        int i = 1;                 // initialization
        do {
            System.out.println(i);
            i++;                   // increment
        } while (i <= 5);          // condition
    }
}

public class Factorial {
    public static void main(String[] args) {
        int number = 5;
        int fact = 1;
        for (int i = 1; i <= number; i++) {
            fact = fact * i;
        }
        System.out.println(fact);
    }
}

